// lib/trisambat-cache.ts
//
// Trisambat API cache layer — browser-safe.
//
// Cache data is imported from cache/trisambat/cached-data.ts, which is
// generated by scripts/refresh-trisambat-cache.ts. Never fetches from
// Trisambat during normal website visits. npm run build does not depend
// on API availability.

export interface TrisambatHolidayEvent {
  ad: string;
  bs: { year: number; month: number; day: number };
  id: string;
  name: { ne: string; en: string };
  category: string;
  holiday: string | null;
  verified: boolean;
}

export interface TrisambatHolidayResponse {
  bsYear: number;
  verified: boolean;
  events: TrisambatHolidayEvent[];
}

export interface TrisambatCacheMeta {
  bsYear: number;
  retrievedAt: string; // ISO timestamp
  sourceUrl: string;
  etag?: string; // HTTP ETag from response, if available
  provisional?: boolean; // true for BS 2084–2090 per API docs
}

export interface TrisambatCacheEntry {
  data: TrisambatHolidayResponse;
  meta: TrisambatCacheMeta;
}

// Statically import the generated cache module. Before the first refresh,
// this exports an empty TRISAMBAT_CACHE. After refresh, it contains the
// fetched API data. The import always resolves because the placeholder
// file always exists.
import { TRISAMBAT_CACHE } from '../cache/trisambat/cached-data';

/** Build the API URL for a BS year. */
export function trisambatHolidaysUrl(bsYear: number): string {
  return `https://trisambat.com/api/v1/holidays/${bsYear}.json`;
}

/**
 * Read cached holiday data for a BS year.
 * Does not fetch. Returns null if no cache data is available.
 * Never throws — returns null if year not cached.
 * Never discards old cache due to age.
 */
export function getTrisambatCacheEntry(
  bsYear: number,
): TrisambatCacheEntry | null {
  const entry = TRISAMBAT_CACHE[bsYear];
  if (!entry) return null;
  return entry as TrisambatCacheEntry;
}

/**
 * Check whether Trisambat data is cached for a given BS year.
 * Does not fetch; only checks available cache data.
 */
export function isTrisambatCached(bsYear: number): boolean {
  return getTrisambatCacheEntry(bsYear) !== null;
}

/**
 * Fetch holiday data for a BS year from the Trisambat API.
 * Returns null if the fetch fails (network error, non-200, invalid JSON).
 * Never throws. Intended for use by the refresh script only.
 */
export async function fetchTrisambatHolidays(
  bsYear: number,
): Promise<{ data: TrisambatHolidayResponse; meta: TrisambatCacheMeta } | null> {
  const url = trisambatHolidaysUrl(bsYear);

  try {
    const response = await fetch(url, { cache: 'no-store' });
    if (!response.ok) {
      return null;
    }

    const etag = response.headers.get('etag') || undefined;
    const data = (await response.json()) as TrisambatHolidayResponse;

    // Validate required fields
    if (
      typeof data.bsYear !== 'number' ||
      !Array.isArray(data.events) ||
      !data.events.every(
        (e) =>
          e.ad &&
          e.bs &&
          typeof e.bs.year === 'number' &&
          typeof e.bs.month === 'number' &&
          typeof e.bs.day === 'number' &&
          e.id &&
          e.name &&
          typeof e.name.en === 'string' &&
          typeof e.name.ne === 'string' &&
          typeof e.category === 'string' &&
          typeof e.verified === 'boolean',
      )
    ) {
      return null;
    }

    const meta: TrisambatCacheMeta = {
      bsYear: data.bsYear,
      retrievedAt: new Date().toISOString(),
      sourceUrl: url,
      etag,
      provisional: data.bsYear >= 2084,
    };

    return { data, meta };
  } catch {
    return null;
  }
}

/**
 * Write holiday data to the in-memory cache.
 * Used only by the refresh script during build time in Node.js.
 * In the browser, this is a no-op — cache writes happen via the refresh
 * script which regenerates cached-data.ts.
 * Never throws.
 */
export function writeTrisambatCacheEntry(
  bsYear: number,
  data: TrisambatHolidayResponse,
  meta: TrisambatCacheMeta,
): boolean {
  // In the browser, this is a no-op — cache writes happen via the refresh
  // script which regenerates cached-data.ts.
  if (typeof window !== 'undefined') {
    return false;
  }
  try {
    (TRISAMBAT_CACHE as Record<number, TrisambatCacheEntry>)[bsYear] = {
      data,
      meta,
    };
    return true;
  } catch {
    return false;
  }
}
